for m in sorted(mod24_counts):
    bar = chr(9608) * mod24_counts[m]
    print(f'  mod24={m:2d}: {mod24_counts[m]:4d} {bar}')

output = {
    'source':'a100_classifier_embedded',
    'total':len(results),'stable':stable,'breach':breach,'neutral':neutral,
    'mod9':{str(k):v for k,v in mod9_counts.items()},
    'mod24':{str(k):v for k,v in mod24_counts.items()},
    'sample':results[:20],
    'timestamp':datetime.now().isoformat()
}

with open('erdos_a100_classification.json','w') as f:
    json.dump(output, f, indent=2)

print(f'\nFile: erdos_a100_classification.json (download from Files)')
